use serde_json::json;use std::io::{self,Read};
#[path="../dp01_view.rs"]mod view;
fn main(){let mut input=String::new();io::stdin().read_to_string(&mut input).unwrap();let args:serde_json::Value=serde_json::from_str(&input).unwrap();let full=std::fs::read_to_string(args["path"].as_str().unwrap()).unwrap();let text=full.lines().take(args["lines"].as_u64().unwrap_or(80) as usize).collect::<Vec<_>>().join("\n");drop(full);let source_bytes=text.len();let lines=text.lines().count();let mut state=vec![json!({"source_id":"report","revision":1,"start_line":1,"end_line":lines,"unit":"one_based_line_inclusive","text":text})];let events=view::bound(&mut state,args["strict"].as_bool().unwrap());let retained=serde_json::to_vec(&state).unwrap().len();let requires_read=state[0]["text"].is_null();let query_text=if requires_read{std::fs::read_to_string(args["path"].as_str().unwrap()).unwrap().lines().take(lines).collect::<Vec<_>>().join("\n")}else{state[0]["text"].as_str().unwrap().to_owned()};println!("{}",json!({"retained_serialized_bytes":retained,"source_bytes":source_bytes,"source_lines":lines,"additional_original_reads":if requires_read{1}else{0},"reread_bytes":if requires_read{query_text.len()}else{0},"query_text_sha_input_unchanged":query_text.len()==source_bytes,"events":events,"state":state}));}
